export function serverT(language: ServerLanguage, key: ServerTranslationKey, values?: ServerTranslationValues) {
  const template = (language === 'tr' ? tr : en)[key];
  if (!values) return template;
  return template.replace(/\{([a-zA-Z0-9_]+)\}/g, (match, name: string) => values[name] === undefined ? match : String(values[name]));
}
